package main

import "fmt"

func main() {
	grid := [][]int{
		{1, 2, 3},
		{4, 5, 6},
		{7, 8, 9},
	}

	total := 0
	for _, row := range grid {
		for _, v := range row {
			total += v
		}
	}
	fmt.Println("Total:", total)

	fmt.Print("Column sums:")
	for c := 0; c < len(grid[0]); c++ {
		sum := 0
		for r := 0; r < len(grid); r++ {
			sum += grid[r][c]
		}
		fmt.Print(" ", sum)
	}
	fmt.Println()

	diag := 0
	for i := 0; i < len(grid); i++ {
		diag += grid[i][i]
	}
	fmt.Println("Diagonal:", diag)
}

